<script setup lang="ts">import {ref} from 'vue';import {useRouter} from 'vue-router';const router=useRouter();const user=JSON.parse(sessionStorage.getItem('user')||'{}');const menus=ref<any[]>(JSON.parse(sessionStorage.getItem('menuTree')||'[]'));function logout(){sessionStorage.clear();router.push('/')}</script>
<template><el-container class="layout"><el-aside width="230px"><h2>内容管理平台</h2><el-menu router><template v-for="m in menus" :key="m.id"><el-sub-menu v-if="m.children?.length" :index="String(m.id)"><template #title>{{m.name}}</template><el-menu-item v-for="c in m.children" :key="c.id" :index="c.path||''">{{c.name}}</el-menu-item></el-sub-menu><el-menu-item v-else :index="m.path||''">{{m.name}}</el-menu-item></template></el-menu></el-aside><el-container><el-header><span>管理后台</span><span>{{user.username||'管理员'}} <el-button link @click="logout">退出</el-button></span></el-header><el-main><h1>欢迎回来，{{user.username||'管理员'}}</h1><div class="cards"><el-card v-for="x in ['内容总量','待审核','本月访问','系统用户']" :key="x"><p>{{x}}</p><strong>1,286</strong></el-card></div></el-main></el-container></el-container></template><style scoped>.layout{height:100vh}.layout aside{background:#172033;color:white}.layout h2{padding:20px}.layout header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #ddd}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}.cards strong{font-size:28px;color:#2563eb}</style>
